mapper.select:
SELECT i.`name_snapshot` AS `name`,
       SUM(i.`quantity`) AS `copies`
FROM `order_item` i
JOIN `orders` o ON o.`id` = i.`order_id`
WHERE o.`status` = 'COMPLETED'
  AND o.`paid_at` >= #{from}
  AND o.`paid_at` < #{to}
GROUP BY i.`name_snapshot`
ORDER BY `copies` DESC, `name` ASC
LIMIT #{topNumber}

SELECT COUNT(*) FROM `dish` d
WHERE d.`status` = 1
  AND NOT EXISTS (
    SELECT 1 FROM `order_item` i
    JOIN `orders` o ON o.`id` = i.`order_id`
    WHERE o.`status` = 'COMPLETED'
      AND o.`paid_at` >= #{from}
      AND o.`paid_at` < #{to}
      AND i.`dish_id` = d.`id`
  )
